// @ts-check
import { createNuxtAppEslintConfig } from '@altafusion/eslint-config'

const baseConfig = createNuxtAppEslintConfig({ vue: true })

const ignoreMarkdown = {
  ignores: ['**/*.md']
}

async function getConfig() {
  try {
    // @ts-expect-error - generated by Nuxt at runtime
    const { default: withNuxt } = await import('./.nuxt/eslint.config.mjs')
    return withNuxt(baseConfig).append(ignoreMarkdown)
  } catch {
    return baseConfig.append(ignoreMarkdown)
  }
}

export default getConfig()
